let nums = [1, 2, 3, 4, 5];

let doubled = nums.map((n) => n * 2);
console.log("2배:", doubled);

let evens = nums.filter((n) => n % 2 === 0);
console.log("짝수:", evens);

let evenDoubled = nums
    .filter((n) => n % 2 === 0)
    .map((n) => n * 2);
console.log("짝수의 2배:", evenDoubled);
